ROOT=Path(__file__).resolve().parents[2];P=ROOT/'data/processed/three_ward_station_surface_risk_v1';R=ROOT/'data/exp/data-preprocessing/three_ward_station_surface_risk_v1';E=ROOT/'data/processed/three_ward_jr_toei_evidence_v1'
