def rr(p):
 with p.open() as f:return list(csv.DictReader(f))
def sha(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def link(p,label=None):return '<a href="'+html.escape(os.path.relpath(p,R),quote=True)+'">'+html.escape(label or p.name)+'</a>'
def table(rows,fields):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(label)+'</th>' for k,label in fields)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x.get(k,'')))+'</td>' for k,label in fields)+'</tr>' for x in rows)+'</tbody></table></div>'
def lines(g):
 if g.geom_type=='Polygon':return [np.array(g.exterior.coords)/1000]
 if g.geom_type in ['LineString','LinearRing']:return [np.array(g.coords)/1000]
 return [a for h in g.geoms for a in lines(h)]
def category(value):return 'Unknown' if value in ['',None] else '>=0.3 m nearby' if float(value)>=.3 else '0.1-0.3 m nearby' if float(value)>=.1 else '<0.1 m on available support'
def main():
 summary=json.loads((R/'summary.json').read_text());validation=json.loads((R/'validation.json').read_text());assert validation['all_passed'];stations=rr(P/'station_screen_summary.csv');entrances=rr(P/'entrance_screen_summary.csv');radius=rr(P/'entrance_scenario_surface_screen.csv');policy=json.loads((P/'screening_contract.json').read_text())
 core=shape(json.loads((ROOT/'data/processed/three_ward_transport_framework_v1/inventory_domains_6677.geojson').read_text())['features'][0]['geometry']);colors={'Unknown':'#969da5','>=0.3 m nearby':'#b84e49','0.1-0.3 m nearby':'#d79741','<0.1 m on available support':'#3b8b8c'};order=list(colors)
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'figure.facecolor':'#f5f8fa','axes.facecolor':'white'})
 fig,axes=plt.subplots(1,2,figsize=(14,10),layout='constrained');env=np.load(P/'display_only_scenario_peak_envelope.npz');a=env['affine'];lo=env['lower'];n,m=lo.shape;extent=[a[2]/1000,(a[2]+m*10)/1000,(a[5]-n*10)/1000,a[5]/1000]
 for ax in axes:
  ax.imshow(np.ma.masked_where(~np.isfinite(lo)|(lo<.1),lo),extent=extent,origin='upper',cmap='Blues',vmin=.1,vmax=1,alpha=.38,interpolation='none');ax.add_collection(LineCollection(lines(core),colors='#2c4657',linewidths=.9,zorder=5));x0,y0,x1,y1=core.buffer(150).bounds;ax.set_xlim(x0/1000,x1/1000);ax.set_ylim(y0/1000,y1/1000);ax.set_aspect('equal');ax.set_xlabel('EPSG:6677 easting (km)');ax.set_ylabel('Northing (km)');ax.grid(alpha=.1)
 for ax,key,title in [(axes[0],'worst_nearby_peak_mean_depth_lower_m','Mapped entrance neighborhoods (20 m)'),(axes[1],'vicinity50m_worst_lower_m','Official station vicinity (50 m buffer)')]:
  if key=='vicinity50m_worst_lower_m':
   valid=[s for s in stations if s['vicinity50m_max_event_peak_exceedance_fraction_ge0p3m']!=''];vals=[100*float(s['vicinity50m_max_event_peak_exceedance_fraction_ge0p3m']) for s in valid];sc=ax.scatter([float(s['x_m'])/1000 for s in valid],[float(s['y_m'])/1000 for s in valid],c=vals,cmap='YlOrRd',vmin=0,vmax=100,s=50,edgecolors='white',linewidths=.4,zorder=8);fig.colorbar(sc,ax=ax,shrink=.55,pad=.02,label='Peak footprint >=0.3 m / admitted ground (%)');ax.set_title('Station vicinity: peak-exceedance ground fraction');continue
  for cat in order:
   ss=[s for s in stations if category(s[key])==cat];ax.scatter([float(s['x_m'])/1000 for s in ss],[float(s['y_m'])/1000 for s in ss],s=45,c=colors[cat],edgecolors='white',linewidths=.5,marker='o' if cat!='Unknown' else 'x',label=cat,alpha=.9,zorder=8)
  ax.set_title(title);ax.legend(loc='upper right',fontsize=8)
 axes[0].text(.02,.02,'Markers locate operator/name inventory units.\nSampling uses mapped entrance neighborhoods,\nnot the marker location.',transform=axes[0].transAxes,fontsize=9,bbox={'facecolor':'white','edgecolor':'none','alpha':.9},zorder=10)
 axes[1].text(.02,.02,'Vicinity exposure does not fill entrance gaps\nor establish flooded platforms, tracks or tunnels.',transform=axes[1].transAxes,fontsize=9,bbox={'facecolor':'white','edgecolor':'none','alpha':.9},zorder=10)
 fig.suptitle('Station flood-risk candidates: surface exposure first',fontsize=18);fig.supxlabel('Existing 16 synthetic-event peak envelopes are non-simultaneous; bins are screening descriptors, not closure thresholds. Unknown is not dry.',fontsize=10);fig.savefig(R/'station_surface_screen_overview.png',dpi=170);plt.close(fig)
 # Neighborhood-size sensitivity is reported as candidate counts, not accuracy.
 rad=[]
 for r in [10,20,30]:
  xs=[x for x in radius if int(x['radius_m'])==r];by=collections.defaultdict(list)
  for x in xs:by[x['osm_node_id']].append(x)
  counts=collections.Counter()
  for id,rrr in by.items():
   ls=[float(x['neighborhood_peak_mean_depth_lower_max_m']) for x in rrr if x['neighborhood_peak_mean_depth_lower_max_m']!=''];counts[category(max(ls) if ls else None)]+=1
  rad.append({'radius_m':r,**dict(counts),'scope':'675 core and explicitly associated near-border source points; no probability'})
 csvwrite(R/'neighborhood_radius_sensitivity.csv',rad)
 operators=[]
 for op in sorted({s['operator'] for s in stations}):
  ss=[s for s in stations if s['operator']==op];cc=collections.Counter(category(s['worst_nearby_peak_mean_depth_lower_m']) for s in ss);operators.append({'operator':op,'station_units':len(ss),'entry_identity_available':sum(int(s['associated_mapped_entrances'])>0 for s in ss),**dict(cc)})
 csvwrite(R/'operator_screen_summary.csv',operators)
 # Keep the finished operator correction auditable after the user deprioritized
 # further circulation-network construction. No additional repair assumptions.
 B=ROOT/'data/processed/three_ward_normal_transport_network_v1';C=E/'corrected_source';old={x['node_id']:x for x in rr(B/'rail_service_candidate_nodes.csv')};new=rr(C/'rail_service_candidate_nodes.csv');changes=[{'node_id':x['node_id'],'route_id':x['route_id'],'station_name':x['name'],'inside_core':x['inside_core'],'old_class':old[x['node_id']]['operator_class'],'new_class':x['operator_class'],'source_stop_id_unchanged':old[x['node_id']]['source_stop_node_id']==x['source_stop_node_id']} for x in new if x['operator_class']!=old[x['node_id']]['operator_class']];csvwrite(E/'operator_classification_corrections.csv',changes)
 topo=[]
 from scipy.sparse import coo_matrix
 from scipy.sparse.csgraph import breadth_first_order
 anchors=rr(ROOT/'data/exp/data-preprocessing/three_ward_normal_transport_network_v1/routing_probe_anchors.csv')
 for branch in ['source_path','conditional_internal']:
  z=np.load(C/(branch+'_multimodal_graph.npz'));keys=z['node_ids'];ix={str(k):i for i,k in enumerate(keys)};u=z['from_index'];vv=z['to_index'];g=coo_matrix((np.ones(len(u),np.uint8),(u,vv)),shape=(len(keys),len(keys))).tocsr()
  for anchor in [x for x in anchors if x['mode']=='walk' and x['kind']=='synthetic_QA_origin_not_population']:
   f=np.zeros(len(keys),bool);b=np.zeros(len(keys),bool);f[breadth_first_order(g,ix[anchor['node_id']],directed=True,return_predecessors=False)]=True;b[breadth_first_order(g.T.tocsr(),ix[anchor['node_id']],directed=True,return_predecessors=False)]=True
   for op in ['jr','toei','metro','other']:
    ns=[x for x in new if x['inside_core']=='True' and x['operator_class']==op];indices=[ix[x['node_id']] for x in ns if x['node_id'] in ix];topo.append({'branch':branch,'origin_ward':anchor['name'],'operator_class':op,'core_source_stop_occurrences':len(ns),'outward':int(f[indices].sum()),'return':int(b[indices].sum()),'both_directions':int((f[indices]&b[indices]).sum()),'not_unique_stations':True,'service_shutdown_not_inferred':True})
 csvwrite(E/'corrected_normal_directional_reachability.csv',topo)
 ck=validation['checks'];validation.update({'operator_correction_nodes':len(changes),'further_station_graph_expansion':'deferred after human priority revision','corrected_source_directional_checks_saved':True,'physical_diagrams_claimed_verified':False});dump(R/'validation.json',validation)
 # A compact evidence ledger explicitly marks every type's limits.
 tiers=[{'evidence':'Mapped source entrance point','available':'673 core OSM points, plus 2 explicitly associated border points','supports':'Surface-neighborhood sampling and source-ID association','does_not_establish':'Current threshold elevation, flood barriers or complete entrance inventory'},{'evidence':'Provider station and transfer descriptions','available':str(summary['provider_evidence_supplement']['toei_station_pages'])+' Toei pages; '+str(summary['provider_evidence_supplement']['jr_station_catalogs'])+' JR identity/service catalogs','supports':'Reported operator/station/service and transfer relationships; existential accessible-route information','does_not_establish':'Verified metric corridors, all gate rights or universal two-way passage'},{'evidence':'Official station-diagram links','available':'Source links retained; image fetch returned invalid challenge pages','supports':'Where diagrams can be reviewed later','does_not_establish':'Image content or specific corridor geometry already inspected'},{'evidence':'Existing depth bounds','available':'16 existing open train/validation parent scenarios, 10 m grid','supports':'Conditional simulated surface exposure under the modeled scenarios','does_not_establish':'Observed flooding, annual probability, point inlet depth or underground water ingress'},{'evidence':'Future shutdown scenarios','available':'Not executed','supports':'Later hypothetical entrance, station and rail-section disruptions','does_not_establish':'Predicted operator decisions'}];csvwrite(P/'evidence_tiers.csv',tiers)
 styles='body{font:16px/1.65 system-ui,sans-serif;background:#f5f7fa;color:#233b4a;max-width:1250px;margin:32px auto;padding:0 24px}h1{font-size:32px;line-height:1.2}h2{font-size:22px;margin-top:34px}.lead{font-size:19px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:#e6eff1;border-radius:8px;padding:16px}.card b{font-size:29px}.notice{background:#fff0da;border-left:4px solid #c28229;padding:15px}.scroll{overflow:auto}table{background:white;border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid #d9e2e8;padding:8px;text-align:left;vertical-align:top}th{background:#e7eff3}img{width:100%;display:block;margin:24px 0;background:white}a{color:#126c82}input{padding:10px;width:340px;max-width:90%;border:1px solid #b2c3ce;border-radius:5px}small{color:#536b7c}@media(max-width:650px){.cards{grid-template-columns:repeat(2,1fr)}}'
 doc='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Station surface-risk screening</title><style>'+styles+'</style><h1>Station flood-risk candidates: surface exposure first</h1><p class="lead">The immediate question is which stations and mapped entrance approaches warrant attention under existing inundation scenarios. Service shutdowns can then be explicit assumptions. Detailed timetables and a complete station-interior reconstruction are not prerequisites for this initial screen.</p>'
 doc+='<div class="cards">'+''.join('<div class="card"><b>'+n+'</b><br>'+label+'</div>' for n,label in [('114','operator/name station identity units'),('673','retained core mapped entrances'),('16','existing synthetic parent scenarios'),('0','new hydraulics / affected counts')])+'</div>'
 doc+='<p class="notice">This is a conditional surface-exposure screen, not a list of stations proven to flood or shut down. The 114 operator/name units represent 154 official station-line records and are not 114 verified interchange complexes. Individual mapped entrances, actual ground thresholds and barriers remain incomplete. Unknown support is never filled as dry.</p><img src="station_surface_screen_overview.png" alt="Whole three-ward station entrance-neighborhood and independent station-vicinity surface exposure screen">'
 doc+='<h2>What the first pass shows</h2><p>Explicit source-area name/operator membership plus an official same-identity geometry check associates 207 of the retained source points to core station units. Only 36 of 114 station units currently have such entrance identity support; 78 remain unresolved at this tier. In at least one existing scenario, 22 units have an associated entrance neighborhood containing admitted ground cells with peak mean depth at or above 0.3 m; nine more reach 0.1–0.3 m. These are screening bins, not ingress, safety or shutdown thresholds.</p><p>The independent station-vicinity layer samples 50 m and 100 m buffers of official station-line geometry. It preserves broader regional coverage without pretending missing entrance identities are repaired. Surface water around an elevated station or above an underground station does not establish water on its platform or track. All 114 station vicinities contain at least one nearby cell reaching 0.1 m in the scenario ensemble, so an any-wet-cell rule alone is poorly discriminating. The right map instead shows the largest event peak-exceedance footprint fraction at 0.3 m; this remains an environmental screening descriptor, not an ingress probability.</p>'+table(operators,[('operator','Operator identity'),('station_units','Station units'),('entry_identity_available','With mapped entrance identity'),('>=0.3 m nearby','Nearby >=0.3 m'),('0.1-0.3 m nearby','Nearby 0.1–0.3 m'),('<0.1 m on available support','Below 0.1 m, available support'),('Unknown','Unknown')])
 doc+='<h2>Interpretation and uncertainty</h2><p>Primary sampling uses 20 m cell-center disks around mapped entrance points on the existing 10 m grid; 10 m and 30 m alternatives are retained below. Only original admitted open-ground labels are used. Peak-depth lower/upper bounds, quarantine and absent support are preserved. These are grid mean depths over eligible open ground, not measured point depths at an inlet, curb or elevated deck.</p><p>A single local maximum can be driven by a small deep cell. The downloadable tables therefore retain the peak-exceedance ground footprint as well as maximum depth and support coverage. That footprint combines per-cell event peaks and need not be inundated simultaneously. Larger neighborhoods generally find more nearby wet cells; this is support sensitivity, not an accuracy estimate.</p>'+table(rad,[('radius_m','Entrance radius (m)'),('>=0.3 m nearby','Nearby >=0.3 m'),('0.1-0.3 m nearby','Nearby 0.1–0.3 m'),('<0.1 m on available support','Below 0.1 m, available support'),('Unknown','Unknown')])
 doc+='<p>All 16 cases are existing synthetic scenarios, spanning peak rainfall rates of 23.14–99.78 mm/h and total rain of about 6.03–40.09 mm, with prescribed river-stage pulses. They do not form a probability sample of observed Tokyo storms. Counts across cases are not annual flood probabilities; event or cross-event peak envelopes are not simultaneous station failures. Numerical qualification does not establish real-world accuracy. Terrain, station and source update epochs are not a single current station survey.</p>'
 doc+='<h2>Station candidate inventory</h2><p>Rows are ordered by the largest admitted peak-exceedance footprint at an associated entrance neighborhood, followed by unresolved stations. This prioritizes a regional screening queue; it is not a ranking of actual station loss or people at risk.</p><input id="filter" placeholder="Filter station, operator or screening state"><div id="inventory">'
 ranked=sorted(stations,key=lambda x:float(x['mapped_entry_largest_peak_exceedance_footprint_ge0p3m_m2'] or -1),reverse=True);shown=[]
 for s in ranked:shown.append({'operator':s['operator'],'station':s['station_name'],'entrances':s['associated_mapped_entrances'],'support':s['entrances_with_admitted_neighborhood'],'entry_state':s['screen_state'],'vicinity_state':s['station_vicinity_status'],'vicinity_percent':round(100*float(s['vicinity50m_max_event_peak_exceedance_fraction_ge0p3m']),1) if s['vicinity50m_max_event_peak_exceedance_fraction_ge0p3m'] else 'unknown','footprint_m2':round(float(s['mapped_entry_largest_peak_exceedance_footprint_ge0p3m_m2']),1) if s['mapped_entry_largest_peak_exceedance_footprint_ge0p3m_m2'] else 'unknown'})
 doc+=table(shown,[('operator','Operator'),('station','Station'),('entrances','Mapped entries'),('support','Entries with support'),('entry_state','Entrance-neighborhood screen'),('vicinity_percent','Station vicinity peak footprint (%)'),('footprint_m2','Largest nearby peak footprint >=0.3 m (m²)')])+'</div><script>document.getElementById("filter").addEventListener("input",function(){const q=this.value.toLowerCase();document.querySelectorAll("#inventory tbody tr").forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?"":"none")})</script>'
 doc+='<h2>Evidence is separate from assumptions</h2>'+table(tiers,[('evidence','Evidence'),('available','Available now'),('supports','Supports'),('does_not_establish','Does not establish')])
 doc+='<p>The prior operator classifier incorrectly matched “Tokyo Metropolitan Bureau of Transportation” as “Tokyo Metro.” A new source-network version fixes this, including Japanese JR aliases and separation of vehicle operator from through-running infrastructure. The old delivery remains unchanged. Corrected normal directional reachability is retained as an appendix; its source stop occurrences must not be confused with unique stations or flood closures.</p><p>'+link(E/'operator_classification_corrections.csv')+' · '+link(E/'corrected_normal_directional_reachability.csv')+' · '+link(E/'provider_transfer_relations.csv')+' · '+link(E/'provider_station_facts.csv')+'</p>'
 doc+='<h2>Next analysis sequence</h2><ol><li>Use the two exposure tiers to define station or station-area flood-risk candidates, preserving unresolved entrance associations and inlet/barrier uncertainty.</li><li>Set transparent service scenarios: selected entrance links closed; selected stations closed/non-stop; selected rail sections suspended. Keep alternative entrances and through-running rules explicit.</li><li>Compare regional accessibility against the matched normal network. Only later combine qualified daytime/nighttime population inputs and definitions for consequence counts.</li></ol><p>No train-by-train timetable, shutdown scenario, new hydraulic run, stranded-person count or new population allocation was executed. The prior official nighttime block baseline and building uncertainty sidecars remain unchanged.</p>'
 doc+='<h2>Reproducible outputs and checks</h2><ul>'+''.join('<li>'+link(p)+'</li>' for p in [P/'station_screen_summary.csv',P/'entrance_screen_summary.csv',P/'entrance_scenario_surface_screen.csv',P/'station_vicinity_scenario_screen.csv',P/'station_entrance_identity_links.csv',P/'entrance_surface_risk_6677.geojson',P/'station_surface_risk_6677.geojson',P/'scenario_bindings.csv',P/'screening_contract.json',R/'summary.json',R/'validation.json',R/'delivery_manifest.json'])+'</ul><p>All original mask and ordered-bound checks pass. The prior transport and population delivery manifests pass hash verification. No sealed test response was opened. Source diagram responses were checked for their PNG signature and correctly rejected as invalid; no visual corridor verification is claimed.</p>'
 doc+='<h2>Primary source examples</h2><p><a href="https://www.kotsu.metro.tokyo.jp/subway/stations/index.html">Toei station catalog</a> · <a href="https://www.kotsu.metro.tokyo.jp/subway/stations/daimon.html">Daimon station and transfer information</a> · <a href="https://www.kotsu.metro.tokyo.jp/subway/stations/mita.html">Mita station and transfer information</a> · <a href="https://www.jreast.co.jp/estation/stations/1039.html">JR Tokyo station information</a> · <a href="https://timetables.jreast.co.jp/timetable/list1039.html">JR Tokyo service catalog</a> · <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors, ODbL 1.0</a></p><p><small>Human priority revision MILI-D-20261016-023 supersedes the immediate ordering in MILI-D-20261016-022. Population uncertainty retained; surface exposure first, hypothetical service disruption later.</small></p></html>'
 (R/'review.html').write_text(doc)
 scripts=[ROOT/'src/preprocessing/screen_station_surface_risk_v1.py',Path(__file__).resolve(),ROOT/'src/preprocessing/fetch_jr_station_evidence_v1.py',ROOT/'src/preprocessing/build_jr_toei_corrected_source_v1.py',ROOT/'src/analyses/validate_station_surface_risk_v1.py'];products=sorted(p for parent in [P,R,E] for p in parent.rglob('*') if p.is_file() and p.name not in ['delivery_manifest.json','delivery_validation.json']);manifest={'human_decision':'MILI-D-20261016-023','products':[{'file':str(p.relative_to(ROOT)),'bytes':p.stat().st_size,'sha256':sha(p)} for p in products],'scripts':[{'file':str(p.relative_to(ROOT)),'sha256':sha(p)} for p in scripts],'prior_deliveries':summary['frozen_deliveries'],'new_hydraulics':False,'shutdown_inferred':False,'affected_people_computed':False,'sealed_tests_opened':False};dump(R/'delivery_manifest.json',manifest)
 from html.parser import HTMLParser
 class Links(HTMLParser):
  def __init__(self):super().__init__();self.paths=[]
  def handle_starttag(self,t,attrs):
   for k,v in attrs:
    if k in ['href','src'] and v and not v.startswith(('http:','https:','#','data:')):self.paths.append(v)
 parser=Links();parser.feed(doc);missing=[x for x in parser.paths if not (R/x).exists()];assert not missing
 dump(R/'delivery_validation.json',{'products':len(products),'scripts':len(scripts),'local_links_checked':len(parser.paths),'missing_links':missing,'all_manifest_files_bound':True,'technical_checks_passed':True,'station_interior_flooding_claimed':False});print('REPORT',len(products),'products',len(scripts),'scripts',flush=True)
if __name__=='__main__':main()
